blocks.css:
#cx .sky{position:relative;width:300px;height:340px;margin:0 auto;border-radius:24px;overflow:hidden;
background:radial-gradient(ellipse at 50% 30%,#1b2a5a 0%,#070b1d 70%);box-shadow:0 20px 40px rgba(0,0,0,.5)}
#cx .sky::before{content:"";position:absolute;inset:0;background-image:radial-gradient(1px 1px at 20% 30%,#fff8,transparent),radial-gradient(1px 1px at 70% 15%,#fff9,transparent),radial-gradient(1.5px 1.5px at 40% 80%,#fff7,transparent),radial-gradient(1px 1px at 85% 60%,#fff8,transparent),radial-gradient(1px 1px at 10% 70%,#fff6,transparent);animation:tw 3s ease-in-out infinite alternate}
@keyframes tw{to{opacity:.4}}
#cx .lines{position:absolute;left:0;top:0;width:300px;height:300px}
#cx .ln{fill:none;stroke:#ffe7a3;stroke-width:2;stroke-linecap:round;filter:drop-shadow(0 0 4px #ffd34d)}
#cx .st{position:absolute;width:34px;height:34px;margin:-17px;border:0;border-radius:50%;background:radial-gradient(circle,#fff 0 20%,#ffe7a3 35%,transparent 70%);
animation:pulse-s 1.6s ease-in-out infinite}
#cx .st.on{background:radial-gradient(circle,#fff 0 30%,#ffd34d 45%,transparent 75%);animation:none;transform:scale(1.3)}
#cx .st.next{box-shadow:0 0 0 2px #ffe7a380}
@keyframes pulse-s{50%{transform:scale(1.25)}}
#cx .hint-s{position:absolute;left:0;right:0;bottom:18px;text-align:center;font:12px var(--label);letter-spacing:2px;text-transform:uppercase;color:#c7cbe0}
#cx .msg{position:absolute;left:0;right:0;bottom:44px;text-align:center;font:italic 700 34px var(--serif);color:#ffe7a3;opacity:0;transform:translateY(10px);transition:1s}
#cx .sky.done .msg{opacity:1;transform:none}#cx .sky.done .hint-s{opacity:0}

