const sky = root.querySelector('.sky'), path = root.querySelector('.ln');
const pts = [[150,95],[95,55],[50,95],[60,160],[150,245],[240,160],[250,95],[205,55],[150,95]];
let i = 0, d = '';
pts.slice(0, -1).forEach(([x, y], k) => {
  const b = document.createElement('button'); b.className = 'st' + (k === 0 ? ' next' : '');
  b.style.left = x + 'px'; b.style.top = y + 'px'; b.setAttribute('aria-label', 'звезда');
  b.addEventListener('click', ev => {
    if (k !== i) { A.vibrate(30); return; }
    b.classList.add('on'); b.classList.remove('next');
    d += (i ? ' L' : 'M') + pts[i].join(' '); i++;
    if (i === pts.length - 1) { d += ' L' + pts[i].join(' '); sky.classList.add('done'); A.act('sky', ev); A.rain(24); }
    else { sky.querySelectorAll('.st')[i].classList.add('next'); A.burst(ev.clientX, ev.clientY, 6, 60); }
    path.setAttribute('d', d);
  });
  sky.appendChild(b);
});
